mapper.sql:
FROM orders INNER JOIN sales_sessions ON sales_sessions.id = orders.sales_session_id
LEFT JOIN dining_tables ON dining_tables.id = sales_sessions.table_id
WHERE sales_sessions.store_id = #{storeId}
  AND orders.created_at >= #{from} AND orders.created_at < #{to}

FROM order_item_cancellation_requests
INNER JOIN order_items ON order_items.id = order_item_cancellation_requests.order_item_id
INNER JOIN orders ON orders.id = order_items.order_id
INNER JOIN sales_sessions ON sales_sessions.id = orders.sales_session_id
LEFT JOIN dining_tables ON dining_tables.id = sales_sessions.table_id
WHERE sales_sessions.store_id = #{storeId}
  AND order_item_cancellation_requests.status = 'APPROVED'
  AND order_item_cancellation_requests.is_remade = TRUE
  AND order_item_cancellation_requests.resolved_at >= #{from}
  AND order_item_cancellation_requests.resolved_at < #{to}
